function patternAlphabetPyramid(n) {
  let alphabet = '';
  for (let i = 0; i < n; i++) alphabet += String.fromCharCode(65 + i);
  let rows = [];
  for (let i = 0; i < n; i++) {
    const spaces = ' '.repeat(n - 1 - i);
    const left = alphabet.slice(0, i + 1);
    const right = left.split('').reverse().slice(1).join('');
    rows.push(spaces + left + right);
  }
  return rows.join('\n');
}
